#define PACKET_SIZE (EVENT_COUNT * 4)

static uint16_t read_u16_be(const unsigned char *p) {
    return ((uint16_t)p[0] << 8) | p[1];
}

static int16_t read_i16_be(const unsigned char *p) {
    uint16_t u = read_u16_be(p);
    int32_t s = (u <= INT16_MAX) ? u : (int32_t)u - 65536;
    return (int16_t)s;
}

/* In the receive loop, use a buffer of at least PACKET_SIZE + 1 bytes. */
unsigned char buffer[PACKET_SIZE + 1];
ssize_t n = recvfrom(sockfd, buffer, sizeof(buffer), 0,
                     (struct sockaddr *)&cli_addr, &cli_len);

if (n != PACKET_SIZE) {
    fprintf(stderr, "Unexpected packet size: %zd bytes\n", n);
    continue;
}

for (size_t offset = 0; offset < PACKET_SIZE; offset += 4) {
    uint16_t index = read_u16_be(buffer + offset);
    int value = read_i16_be(buffer + offset + 2);

    if (index < EVENT_COUNT) {
        libevdev_uinput_write_event(controller,
            REGISTERED_EVENTS[index].type,
            REGISTERED_EVENTS[index].code,
