Claro! Vamos criar um componente personalizado usando Shadow DOM que atenda aos requisitos mencionados. Este componente será chamado de `<x-custom-details>`. Ele terá uma visualização semelhante ao elemento `<details>`, mas com algumas diferenças importantes:

1. A primeira parte (`intro`) estará sempre visível mesmo quando o detalhe estiver colapsado.
2. Um ícone quadrado (+/-) aparecerá antes do cabeçalho.
3. O cabeçalho possui uma borda inferior e tamanho maior da fonte.
4. Quando não expandido, há um botão “Expandir Mais”.

Aqui está o código completo para este componente:

```html
<template id="x-custom-details-template">
  <style>
    /* Estilos internos */
    #root {
      position: relative;
    }

    #icon {
      display: inline-block;
      width: 20px;
      height: 20px;
      line-height: 20px;
      text-align: center;
      margin-right: 8px;
      cursor: pointer;
    }

    [slot='header'] {
      font-size: 1.2em; /* Tamanho ligeiramente maior */
      border-bottom: 1px solid #ccc; /* Borda inferior leve */
      padding: 5px 0;
      color: #333;
      white-space: nowrap;
    }

    #intro {
      margin-top: -4px; /* Alinha verticalmente com o cabeçalho */
      padding: 10px 15px;
      background-color: #f9f9f9;
      box-sizing: content-box;
    }

    #more-button {
      display: block;
      margin-top: -8px; /* Centraliza horizontalmente */
      padding: 6px 12px;
      background-color: transparent;
      border: none;
      color: #6c757d;
      text-decoration: underline;
      cursor: pointer;
    }

    #content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.5s ease-in-out;
    }
  </style>

  <div id="root">
    <div id="icon">+</div> <!-- Ícone inicial -->
    <slot name="header"></slot> <!-- Cabeçalho -->
    <div id="intro"><slot></slot><!-- Parte introdutória --></div>
    <div id="content">
      <slot name="details"></slot> <!-- Conteúdo detalhado -->
    </div>
    <div id="more-button">Expandir Mais</div>
  </div>
</template>

<script>
document.registerElement('x-custom-details', {
  extends: 'div',
  prototype: Object.assign(Object.create(HTMLDivElement.prototype), {
    attributeNameChangedCallback(attr, oldValue, newValue) {
      if (this.hasAttributeNS("http://www.w3.org/1999/xhtml", "open") && !oldValue) {
        this._toggleIcon();
      }
    },
    connectedCallback() {
      const template = document.getElementById('x-custom-details-template');
      this.attachShadow({ delegateTo: null }).appendChild(template.content);

      // Configuração inicial dos ícones e botões
      this._setupInitialState();

      // Adiciona ouvintes de eventos
      this.addEventListener('click', event => {
        if ((event.target === this.querySelector('#icon') ||
            event.target === this.querySelector('#more-button'))) {
          this._toggleContentVisibility();
        } else if (event.target.matches('.formcontrol')) { // Exemplo adicional de evento
          console.log(`Clicked form control ${event.target}`);
        }
      });
    },
    disconnect() {},
    attributeChangedCallback(name, oldValue, newValue) {},
    _toggleIcon() {
      const iconText = this.getAttribute('open') ? '-': '+';
      this.shadowRoot.querySelector('#icon').innerText = iconText;
    },
    _setupInitialState() {
      const openAttr = this.hasAttributeNS("http://www.w3.org/1999/xhtml", "open");
      this._toggleIcon();
      this._setHeightBasedOnOpenStatus(openAttr);
    },
    _setHeightBasedOnOpenStatus(isOpen) {
      const contentEl = this.shadowRoot.querySelector('#content');
      contentEl.style.maxHeight = isOpen ? 'none' : '0';
    },
    _toggleContentVisibility() {
      const currentOpenState = !!parseInt(this.getAttributeOrDefault('open'), 10) + 1;
      this.setAttributeWithDefaultIfNeeded('open', String(currentOpenState));
      this._toggleIcon();
      this._setHeightBasedOnOpenStatus(!Number(this.getAttributeOrDefault('open', 0)));
    },
    getAttributeOrDefaultIfNeeded(attrName) {
